export function getMockSummary(): DiagnosticSummary {
  const faults = mockCases.filter((c) => c.payload?.['Diagnostic Status'] === 'FAULT FOUND').length;
  const working = mockCases.filter((c) => c.payload?.['Diagnostic Status'] === 'WORKING SATISFACTORY').length;
  const closedAdmin = mockCases.filter((c) => c.payload?.['Diagnostic Status'] === 'CLOSED_BY_ADMIN' || c.payload?.['Diagnostic Status'] === 'CLOSED BY ADMIN').length;
  const incomplete = mockCases.filter((c) => !['FAULT FOUND', 'WORKING SATISFACTORY', 'CLOSED_BY_ADMIN', 'CLOSED BY ADMIN'].includes(c.payload?.['Diagnostic Status'] || '')).length;

  return {
    total: mockCases.length,
    faults,
    working,
    incomplete,
    totalHours: 54.2,
    averageCompletionHours: 0.42,
    open: incomplete,
    inProgress: incomplete,
    completed: working + closedAdmin,
    escalations: faults,
    techniciansTotal: mockUsers.length,
    techniciansActive: mockUsers.filter((u) => u.active).length,
    manufacturers: ['TATA MOTORS', 'ASHOK LEYLAND', 'VECV'],
  };
}
